@props([    'compact' => false,])<div    x-data="{        tracking: '',        error: '',        isValidTrackingNumber(num) {            const n = num.trim().toUpperCase();            return /^GEX-\d{4}-[A-Z0-9]{8}$/.test(n)                || /^FDX-\d{4}-[A-Z0-9]{8}$/.test(n)                || /^TRK-[A-Z0-9]{10}$/.test(n)                || /^LOG-[A-Z0-9]{10}$/.test(n);        },        submit() {            const normalized = this.tracking.trim().toUpperCase();            if (!normalized) return;            if (!this.isValidTrackingNumber(normalized)) {                this.error = 'Tracking number not found';                return;            }            this.error = '';            window.location.href = '/tracking/' + encodeURIComponent(normalized);        }    }"    class="w-full">    @if(!$compact)        <h2 class="text-xl font-semibold text-navy-900">Track your shipment</h2>        <p class="mt-2 text-sm text-slate-600">Enter your tracking number to see real-time status, route updates, and delivery progress.</p>    @endif    <form @submit.prevent="submit()" class="mt-4 flex flex-col gap-3 sm:flex-row">        <div class="relative flex-1">            <input                x-model="tracking"                type="text"                placeholder="GEX-2026-ABC12345"                class="focus-ring min-h-12 w-full rounded-xl border border-navy-200 bg-white px-4 text-sm text-navy-900 placeholder:text-slate-400 transition-colors hover:border-navy-300 focus:border-azure-400"            />            <template x-if="error">                <p class="mt-1 text-xs text-red-500" x-text="error"></p>            </template>        </div>        <button type="submit" class="focus-ring inline-flex items-center justify-center gap-2 rounded-full bg-azure-500 px-6 py-3 text-sm font-semibold text-white shadow-glow transition-all duration-200 hover:bg-azure-600 hover:-translate-y-0.5">            <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>            Track        </button>    </form></div>
